@Test
public void TestOldBloomFilters() throws Exception {
    OrcProto.StripeFooter footer = OrcProto.StripeFooter.newBuilder().addStreams(OrcProto.Stream.newBuilder().setColumn(1).setKind(OrcProto.Stream.Kind.ROW_INDEX).setLength(1000).build()).addStreams(OrcProto.Stream.newBuilder().setColumn(1).setKind(OrcProto.Stream.Kind.BLOOM_FILTER).setLength(1000).build()).addStreams(OrcProto.Stream.newBuilder().setColumn(2).setKind(OrcProto.Stream.Kind.ROW_INDEX).setLength(1000).build()).addStreams(OrcProto.Stream.newBuilder().setColumn(2).setKind(OrcProto.Stream.Kind.BLOOM_FILTER).setLength(1000).build()).addStreams(OrcProto.Stream.newBuilder().setColumn(3).setKind(OrcProto.Stream.Kind.ROW_INDEX).setLength(1000).build()).addStreams(OrcProto.Stream.newBuilder().setColumn(3).setKind(OrcProto.Stream.Kind.BLOOM_FILTER).setLength(1000).build()).build();
    TypeDescription schema = TypeDescription.fromString("struct<x:int,y:decimal(10,2),z:string>");
    OrcProto.Stream.Kind[] bloomFilterKinds = new OrcProto.Stream.Kind[4];
    // normal read
    DiskRangeList ranges = RecordReaderUtils.planIndexReading(schema, footer, false, new boolean[] { true, true, false, true }, new boolean[] { false, true, false, true }, OrcFile.WriterVersion.HIVE_4243, bloomFilterKinds);
    assertEquals(OrcProto.Stream.Kind.BLOOM_FILTER, bloomFilterKinds[1]);
    assertEquals(OrcProto.Stream.Kind.BLOOM_FILTER, bloomFilterKinds[3]);
    assertEquals("range start: 0 end: 2000", ranges.toString());
    assertEquals("range start: 4000 end: 6000", ranges.next.toString());
    assertEquals(null, ranges.next.next);
    // ignore non-utf8 bloom filter
    Arrays.fill(bloomFilterKinds, null);
