    list.noNulls = false;
    for (int r = 0; r < 1024; ++r) {
        if (r < 200) {
            list.isNull[r] = true;
        } else if (r < 300) {
            list.offsets[r] = r - 200;
            list.lengths[r] = 1;
        } else if (r < 400) {
            list.isNull[r] = true;
        } else if (r < 500) {
            list.offsets[r] = r - 300;
            list.lengths[r] = 1;
        } else if (r < 600) {
            list.isNull[r] = true;
        } else if (r < 700) {
            list.offsets[r] = r;
            list.lengths[r] = 2;
        } else {
            list.isNull[r] = true;
        }
        ((LongColumnVector) list.child).vector[r] = r * 10;
    }
    writer.addRowBatch(batch);
    writer.close();
    Reader reader = OrcFile.createReader(testFilePath, OrcFile.readerOptions(conf));
